package org.pocketlore.app;
import android.app.*;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Frozen public retrieval/resource diagnostics on actual installed full collections. */
public final class HybridRetrievalInstrumentation extends Instrumentation {
 JSONArray checks=new JSONArray(),searches=new JSONArray(),reads=new JSONArray();JSONObject report=new JSONObject();String mode;
 void ok(boolean value,String label){if(!value)throw new AssertionError(label);checks.put(label);}
 public void onCreate(Bundle b){super.onCreate(b);mode=b.getString("mode","baseline");start();}
 void clear()throws Exception{try{ScaleWiki.class.getDeclaredMethod("clearPreviewCache").invoke(null);}catch(NoSuchMethodException absent){if(!mode.equals("baseline"))throw absent;}}
 boolean cached(ScaleWiki.Read r)throws Exception{try{return ScaleWiki.Read.class.getDeclaredField("cacheHit").getBoolean(r);}catch(NoSuchFieldException absent){return false;}}
 long pss(){Debug.MemoryInfo m=new Debug.MemoryInfo();Debug.getMemoryInfo(m);return m.getTotalPss();}
 public void onStart(){Bundle result=new Bundle();try{
  File files=getTargetContext().getFilesDir();ScaleLibrary library=new ScaleLibrary(files);ScaleLibrary.Entry wiki=null;int wikiShards=0,placeShards=0;
  for(ScaleLibrary.Entry e:library.entries()){int count=e.manifest.getJSONArray("shards").length();if(e.kind().equals("wiki")){wiki=e;wikiShards+=count;}else placeShards+=count;}
  ok(wiki!=null&&wikiShards+placeShards==31,"All31 shards simultaneously installed");report.put("wiki_shards",wikiShards).put("places_shards",placeShards).put("mode",mode).put("pss_before_kib",pss());
  ScaleWiki.Hit largest=null;long largestRaw=0;JSONArray shards=wiki.manifest.getJSONArray("shards");
  for(int i=0;i<shards.length();i++){String shard=shards.getString(i);JSONArray b=NativeIndex.rows(ScaleWiki.database(wiki,shard).getPath(),"SELECT id,raw_length FROM blocks ORDER BY raw_length DESC LIMIT 1",new String[]{},1,()->false).getJSONArray(0);long raw=Long.parseLong(b.getString(1));if(raw>largestRaw){JSONArray a=NativeIndex.rows(ScaleWiki.database(wiki,shard).getPath(),"SELECT id FROM articles WHERE block_id=? AND length<=33554432 ORDER BY length LIMIT 1",new String[]{b.getString(0)},1,()->false);if(a.length()>0){largest=ScaleWiki.byId(wiki,shard,a.getJSONArray(0).getString(0),()->false);largestRaw=raw;}}}
  ok(largestRaw>=23473862,"Actual oversized raw block exceeds23MB");report.put("largest_raw_block_bytes",largestRaw).put("largest_article",largest.identity());clear();
  String previous=null;for(int i=0;i<3;i++){long start=SystemClock.elapsedRealtimeNanos();ScaleWiki.Read read=ScaleWiki.read(largest,getTargetContext().getCacheDir(),()->false);long nanos=SystemClock.elapsedRealtimeNanos()-start;ok(previous==null||previous.equals(read.text),"Repeated exact preview retained");previous=read.text;reads.put(new JSONObject().put("iteration",i).put("ms",nanos/1e6).put("cache_hit",cached(read)).put("pss_kib",pss()).put("raw_block_bytes",read.rawBlockBytes).put("temporary_bytes",read.temporaryBytes));if(!mode.equals("baseline"))ok(cached(read)==(i>0),"Cold then warm cache behavior");}
  if(!mode.equals("baseline")){
   ScaleWiki.Read caller=ScaleWiki.read(largest,getTargetContext().getCacheDir(),()->false);String original=caller.text;caller.text="Mutated caller value";ok(ScaleWiki.read(largest,getTargetContext().getCacheDir(),()->false).text.equals(original),"Caller cannot mutate cached preview");
   JSONArray badRow=new JSONArray();for(Object value:new Object[]{largest.id,largest.title,largest.tier,largest.rights,largest.url,largest.date,largest.revision,largest.sourceRow,largest.sourceHash,Long.toString(largest.block),Long.toString(largest.offset),Long.toString(largest.length),"0".repeat(64)})badRow.put(value);
   ScaleWiki.Hit bad=new ScaleWiki.Hit(largest.edition,largest.shard,badRow);boolean rejected=false;try{ScaleWiki.read(bad,getTargetContext().getCacheDir(),()->false);}catch(IOException e){rejected=true;}ok(rejected,"Changed record checksum cannot reuse verified cache entry");
  }
  ScaleWiki.Hit fixed=largest;boolean cancelled=false;try{ScaleWiki.read(fixed,getTargetContext().getCacheDir(),()->true);}catch(InterruptedIOException e){cancelled=true;}ok(cancelled,"Cancellation precedes warm cache return");clear();AtomicInteger polls=new AtomicInteger();cancelled=false;long start=SystemClock.elapsedRealtime();try{ScaleWiki.read(fixed,getTargetContext().getCacheDir(),()->polls.incrementAndGet()>8);}catch(InterruptedIOException e){cancelled=true;}ok(cancelled,"Cancellation during actual oversized stream");report.put("cancel_ms",SystemClock.elapsedRealtime()-start);
  int scanned=0;for(File f:Objects.requireNonNull(getTargetContext().getCacheDir().listFiles()))if(f.getName().startsWith("scale-record-"))scanned++;ok(scanned==0,"Cancelled reader removes temporary record");
  String[] queries={"Photosynthesis","How do plants convert sunlight into chemical energy?","French Revolution","How are prime numbers different from composite numbers?","Operating system","Rights and duties of citizenship","Public transport in Japan","NoSuchTopicZqxv370Evidence"};List<ScaleWiki.Hit> candidates=new ArrayList<>();
  for(String q:queries){long begin=SystemClock.elapsedRealtime();List<ScaleWiki.Hit> hits=ScaleWiki.search(wiki,q,()->false);JSONArray ids=new JSONArray();Set<String> seen=new HashSet<>();for(ScaleWiki.Hit hit:hits){ok(seen.add(hit.identity()),"Distinct article identity");ok(!hit.mayGenerate(),"Bulk source stays generation denied");ids.put(hit.identity());if(candidates.size()<8&&candidates.stream().noneMatch(h->h.identity().equals(hit.identity())))candidates.add(hit);}searches.put(new JSONObject().put("query",q).put("ms",SystemClock.elapsedRealtime()-begin).put("identities",ids));if(q.startsWith("NoSuch"))ok(hits.isEmpty(),"Invented token has no retrieved evidence");}
  clear();ScaleWiki.read(largest,getTargetContext().getCacheDir(),()->false);for(ScaleWiki.Hit hit:candidates)ScaleWiki.read(hit,getTargetContext().getCacheDir(),()->false);
  ScaleWiki.Read evicted=ScaleWiki.read(largest,getTargetContext().getCacheDir(),()->false);if(!mode.equals("baseline")){ok(!cached(evicted),"LRU entry evicted by distinct previews");long[] state=(long[])ScaleWiki.class.getDeclaredMethod("previewCacheState").invoke(null);ok(state[0]<=4&&state[1]<=524288,"Cache count and accounted bytes bounded");report.put("cache_state",new JSONArray(state));clear();ok(!cached(ScaleWiki.read(largest,getTargetContext().getCacheDir(),()->false)),"Memory-pressure clear requires verified reread");}
  report.put("pss_after_kib",pss()).put("app_data_bytes",SharedShardUpdate.uniqueBytes(new File(getTargetContext().getApplicationInfo().dataDir))).put("status","PASS");
 }catch(Throwable e){try{report.put("status","FAIL").put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}}
 finally{try{report.put("checks",checks).put("searches",searches).put("reads",reads);Files.write(new File(getTargetContext().getFilesDir(),"hybrid-"+mode+".json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));result.putString("report",report.toString());}catch(Exception e){result.putString("error",e.toString());}finish(report.optString("status").equals("PASS")?-1:1,result);}}
}
